package com.travbook.stays.adapter.in.web;
import com.travbook.stays.domain.model.Stay.*;
import com.travbook.stays.application.port.in.HotelStays.*;
import com.travbook.hotels.domain.model.*;
import java.time.*;
import java.util.*;
final class StayViews {
 record Money(String amount,String currency){static Money of(HotelMoney m){return new Money(m.amount().toPlainString(),m.currency());}}
 record Property(String id,String name,String address,String city,String timezone,String checkInTime,String checkOutTime){static Property of(HotelProperty p){return new Property(p.id(),p.name(),p.address(),p.city(),p.timezone(),p.checkInTime(),p.checkOutTime());}}
 record Night(LocalDate date,Money amount){}
 record Offer(UUID id,String propertyId,String supplier,int roomIndex,String roomType,HotelOffer.Plan planCode,HotelOffer.Meal mealPlan,int maxAdults,int maxChildren,HotelCriteria.Occupancy occupancy,List<String> amenities,List<Night> nights,Money subtotal,Money taxes,Money fees,Money total,boolean refundable,Instant freeCancellationUntil,String cancellationPolicy,String paymentCondition,Instant observedAt,Instant expiresAt){static Offer of(HotelOffer o){return new Offer(o.id(),o.propertyId(),o.supplier(),o.roomIndex(),o.roomType(),o.planCode(),o.mealPlan(),o.maxAdults(),o.maxChildren(),o.occupancy(),o.amenities(),o.nights().stream().map(n->new Night(n.date(),Money.of(n.amount()))).toList(),Money.of(o.subtotal()),Money.of(o.taxes()),Money.of(o.fees()),Money.of(o.total()),o.refundable(),o.freeCancellationUntil(),o.cancellationPolicy(),o.paymentCondition(),o.observedAt(),o.expiresAt());}}
 record QuoteView(UUID id,int version,String mode,Property property,HotelCriteria criteria,List<Offer> offers,Money previousTotal,Money total,Instant createdAt,Instant expiresAt,Instant acceptedAt,boolean expired,UUID bookingId){static QuoteView of(QuoteDetails d){var q=d.quote();var s=q.selection();return new QuoteView(q.id(),q.version(),"MOCK",Property.of(s.property()),s.criteria(),s.offers().stream().map(o->Offer.of(o)).toList(),Money.of(s.previousTotal()),Money.of(s.total()),q.createdAt(),q.effectiveExpiry(),d.acceptedAt(),d.expired(),d.bookingId());}}
 record BookingView(UUID id,String mode,QuoteView quote,List<Guest> guests,SpecialRequest specialRequest,Scenario scenario,long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,Money refundAmount,boolean terminal){static BookingView of(Booking b,Instant now){return new BookingView(b.id(),"MOCK",QuoteView.of(new QuoteDetails(b.quote(),b.acceptedAt(),b.id(),b.quote().expired(now))),b.guests(),b.specialRequest(),b.scenario(),b.version(),b.createdAt(),b.updatedAt(),b.status(),b.payment(),b.reservation(),b.refund(),b.step(),b.supplierReference(),b.paymentReference(),b.refundReference(),b.failureCode(),Money.of(b.cancellation()==null?HotelMoney.inr(java.math.BigDecimal.ZERO):b.cancellation().quote().refundAmount()),b.terminal());}}
 record BookingV2View(UUID id,String mode,QuoteView quote,List<Guest> guests,SpecialRequest specialRequest,Scenario scenario,long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,Money refundAmount,boolean terminal,QuoteView currentQuote,List<AmendmentView> amendments,Money amountDueAtProperty){static BookingV2View of(Booking b,Instant now){return new BookingV2View(b.id(),"MOCK",QuoteView.of(new QuoteDetails(b.quote(),b.acceptedAt(),b.id(),b.quote().expired(now))),b.guests(),b.specialRequest(),b.scenario(),b.version(),b.createdAt(),b.updatedAt(),b.status(),b.payment(),b.reservation(),b.refund(),b.step(),b.supplierReference(),b.paymentReference(),b.refundReference(),b.failureCode(),Money.of(b.cancellation()==null?HotelMoney.inr(java.math.BigDecimal.ZERO):b.cancellation().quote().refundAmount()),b.terminal(),QuoteView.of(new QuoteDetails(b.currentQuote(),b.currentQuote().id().equals(b.quote().id())?b.acceptedAt():null,b.id(),b.currentQuote().expired(now))),b.amendments().stream().map(a->new AmendmentView(a.id(),QuoteView.of(new QuoteDetails(a.quote(),null,b.id(),a.quote().expired(now))),a.state(),a.requestedAt())).toList(),Money.of(b.deferred()&&b.status()!=Status.CANCELLED&&b.status()!=Status.FAILED?b.currentQuote().selection().total():HotelMoney.inr(java.math.BigDecimal.ZERO)));}}
 record BookingV3View(UUID id,String mode,QuoteView quote,List<Guest> guests,SpecialRequest specialRequest,Scenario scenario,long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,Money refundAmount,boolean terminal,QuoteView currentQuote,List<AmendmentView> amendments,Money amountDueAtProperty,List<ChangeView> changes){static BookingV3View of(Booking b,Instant now){return new BookingV3View(b.id(),"MOCK",QuoteView.of(new QuoteDetails(b.quote(),b.acceptedAt(),b.id(),b.quote().expired(now))),b.currentGuests(),b.specialRequest(),b.scenario(),b.version(),b.createdAt(),b.updatedAt(),b.status(),b.payment(),b.reservation(),b.refund(),b.step(),b.supplierReference(),b.paymentReference(),b.refundReference(),b.failureCode(),Money.of(b.cancellation()==null?HotelMoney.inr(java.math.BigDecimal.ZERO):b.cancellation().quote().refundAmount()),b.terminal(),QuoteView.of(new QuoteDetails(b.currentQuote(),b.currentQuote().id().equals(b.quote().id())?b.acceptedAt():null,b.id(),b.currentQuote().expired(now))),b.amendments().stream().map(a->new AmendmentView(a.id(),QuoteView.of(new QuoteDetails(a.quote(),null,b.id(),a.quote().expired(now))),a.state(),a.requestedAt())).toList(),Money.of(b.deferred()&&b.status()!=Status.CANCELLED&&b.status()!=Status.FAILED?b.currentQuote().selection().total():HotelMoney.inr(java.math.BigDecimal.ZERO)),b.changes().stream().map(c->ChangeView.of(c,now,b.id())).toList());}}
 record ChangeView(UUID id,QuoteView quote,List<Guest> guests,com.travbook.stays.domain.model.StayChange.State state,Payment payment,Refund refund,Instant createdAt,Instant acceptedAt,UUID sourcePaymentId,Money sourceAmount){static ChangeView of(com.travbook.stays.domain.model.StayChange c,Instant now,UUID booking){return new ChangeView(c.id(),QuoteView.of(new QuoteDetails(c.quote(),c.acceptedAt(),booking,c.quote().expired(now))),c.guests(),c.state(),c.payment(),c.refund(),c.createdAt(),c.acceptedAt(),c.quote().collectionMethod()==CollectionMethod.PAY_NOW?c.sourcePaymentId():null,Money.of(c.sourceAmount()));}}
 record ChangeQuoteView(QuoteView quote,long bookingVersion,Money newCharge,Money expectedRefund,String netDifference){static ChangeQuoteView of(ChangeQuote q){return new ChangeQuoteView(QuoteView.of(q.details()),q.bookingVersion(),Money.of(q.newCharge()),Money.of(q.expectedRefund()),q.netDifference().toPlainString());}}
 record AmendmentView(UUID id,QuoteView quote,AmendmentState state,Instant requestedAt){}
 record Summary(UUID id,String propertyName,LocalDate checkIn,LocalDate checkOut,String mode,Status status,Payment payment,Reservation reservation,Refund refund,Money total,Instant createdAt){static Summary of(Booking b){return new Summary(b.id(),b.currentQuote().selection().property().name(),b.currentQuote().selection().criteria().checkIn(),b.currentQuote().selection().criteria().checkOut(),"MOCK",b.status(),b.payment(),b.reservation(),b.refund(),Money.of(b.currentQuote().selection().total()),b.createdAt());}}
 record ListView(List<Summary> items,UUID nextCursor){}
 record CancellationView(UUID id,UUID bookingId,long bookingVersion,Money refundAmount,Money retainedAmount,Instant createdAt,Instant expiresAt,String mode){static CancellationView of(CancellationQuote q){return new CancellationView(q.id(),q.bookingId(),q.bookingVersion(),Money.of(q.refundAmount()),Money.of(q.retainedAmount()),q.createdAt(),q.expiresAt(),"MOCK");}}
 record VoucherView(UUID id,UUID bookingId,String kind,String mode,Instant createdAt,String sha256,int byteLength,String downloadUrl){static VoucherView of(Voucher v){return new VoucherView(v.id(),v.bookingId(),"MOCK_ACCOMMODATION_VOUCHER","MOCK",v.createdAt(),v.sha256(),v.byteLength(),"/api/v1/stay-bookings/"+v.bookingId()+"/voucher/content");}}
 record VoucherV2View(UUID id,UUID bookingId,String kind,String mode,Instant createdAt,String sha256,int byteLength,String downloadUrl){static VoucherV2View of(Voucher v){return new VoucherV2View(v.id(),v.bookingId(),"MOCK_ACCOMMODATION_VOUCHER","MOCK",v.createdAt(),v.sha256(),v.byteLength(),"/api/v2/stay-bookings/"+v.bookingId()+"/voucher/content");}}
 record VoucherV3View(UUID id,UUID bookingId,String kind,String mode,Instant createdAt,String sha256,int byteLength,String downloadUrl){static VoucherV3View of(Voucher v){return new VoucherV3View(v.id(),v.bookingId(),"MOCK_ACCOMMODATION_VOUCHER","MOCK",v.createdAt(),v.sha256(),v.byteLength(),"/api/v3/stay-bookings/"+v.bookingId()+"/voucher/content");}}
 record EventView(UUID eventId,String eventType,long aggregateVersion,Instant occurredAt,String mode,String status,String payment,String reservation,String refund){static EventView of(Event e){return new EventView(e.eventId(),e.eventType(),e.aggregateVersion(),e.occurredAt(),"MOCK",e.status(),e.payment(),e.reservation(),e.refund());}}
}
